ALTER TABLE discoveries
ADD COLUMN discovery_type TEXT NOT NULL DEFAULT 'unclassified';

ALTER TABLE discoveries
ADD COLUMN validation_stage TEXT NOT NULL DEFAULT 'not_assessed';

DROP INDEX IF EXISTS discoveries_source_url_idx;
CREATE INDEX IF NOT EXISTS discoveries_source_url_idx ON discoveries(source_url);
CREATE INDEX IF NOT EXISTS discoveries_type_idx ON discoveries(discovery_type);
CREATE INDEX IF NOT EXISTS discoveries_validation_stage_idx ON discoveries(validation_stage);
CREATE UNIQUE INDEX IF NOT EXISTS discoveries_intake_external_idx
  ON discoveries(intake_source, external_id)
  WHERE intake_source IS NOT NULL AND external_id IS NOT NULL;

