INSERT OR IGNORE INTO editorial_events (
  id,
  discovery_id,
  from_status,
  to_status,
  note,
  actor,
  created_at
)
SELECT
  'global-backfill-' || id,
  id,
  CASE WHEN status = 'verified' THEN 'under_review' ELSE 'candidate' END,
  status,
  verification_note,
  'editorial research',
  COALESCE(verified_at, review_started_at, CURRENT_TIMESTAMP)
FROM discoveries
WHERE intake_source = 'editorial_research';
